CREATE TABLE P360_RECEIPTS (EVENT_ID VARCHAR2(36) PRIMARY KEY, TYPE VARCHAR2(40) NOT NULL, OWNER_ID VARCHAR2(250) NOT NULL, ORDER_ID NUMBER(19) NOT NULL, STORE_ID NUMBER(19) NOT NULL, PROCESSED_AT TIMESTAMP WITH TIME ZONE NOT NULL, ARTIFACT VARCHAR2(100) NOT NULL);
CREATE INDEX IDX_RECEIPT_OWNER ON P360_RECEIPTS(OWNER_ID);
